def txt(b64): return base64.b64decode(b64).decode('utf-8')
def sha(t): return hashlib.sha256(t.encode('utf-8')).hexdigest()
def p(rel): return os.path.join(ROOT, *rel.split('/'))
def falha(m): print('NADA foi alterado.\n  - ' + m + '\n  Me mande o arquivo atual que eu ajusto o script.'); sys.exit(1)
def leia(rel):
    raw = open(p(rel), 'rb').read(); bom = raw.startswith(b'\xef\xbb\xbf'); t = raw[3:].decode('utf-8') if bom else raw.decode('utf-8'); return t.replace('\r\n', '\n'), '\r\n' in t, bom
def grave(rel, t, crlf, bom):
    os.makedirs(os.path.dirname(p(rel)), exist_ok=True); b = (t.replace('\n', '\r\n') if crlf else t).encode('utf-8'); open(p(rel), 'wb').write((b'\xef\xbb\xbf' + b) if bom else b)
