VITAL = "        <VitalBlock total={commercial.forecast} monthly={commercial.monthlyForecast} detail={commercial.forecastDetail} />\n"
BLK_A = VITAL + "      </div>\n"; BLK_N = VITAL + "\n" + COMENT + L_V2 + "      </div>\n"                       # âncora principal: o fim da pilha, logo depois da "Saúde da recorrência"
ALT_A = "      </div>\n\n      <DealsModal query={dealsQ}"; ALT_N = "\n" + COMENT + L_V2 + ALT_A                                    # âncora de reserva: o fim da pilha, logo antes do popup de negócios

def onde_monta():
    achados = []
    base = p('app')
    for r, ds, fns in os.walk(base):
        ds[:] = [d for d in ds if d not in ('node_modules', '.next')]
        for fn in fns:
            if not fn.endswith(('.tsx', '.jsx')): continue
            rel = os.path.relpath(os.path.join(r, fn), ROOT).replace(os.sep, '/')
            try: linhas = open(os.path.join(r, fn), 'rb').read().decode('utf-8', errors='replace').replace('\r', '').split('\n')
            except OSError: continue
            for i, l in enumerate(linhas):
                if '<ForecastSection' in l and 'function ForecastSection' not in l: achados.append((rel, i + 1, l.strip()[:120], (linhas[i - 1].strip()[:120] if i else '')))
    return achados

